package net.civeira.phylax.features.document.themeasset.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ContentVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property content of theme asset ")
  void test_content_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ContentVO.tryFrom(null));
    Assertions.assertEquals("file_1", ContentVO.from("file_1").getContent());
    Assertions.assertEquals("[" + "file_1" + "]", ContentVO.fromTemporal("file_1").toString());
    Assertions.assertFalse(ContentVO.from("file_1").isContentTemporal());
    Assertions.assertTrue(ContentVO.fromTemporal("file_1").isContentTemporal());
    Assertions.assertEquals("[" + "file_1" + "]", ContentVO.from("file_1").toString());
    Assertions.assertFalse(ContentVO.tryFrom("1").isContentTemporal());
    Assertions.assertTrue(ContentVO.tryFrom("temp://1").isContentTemporal());
  }
}
